import { Suspense } from 'react'
import { getProducts } from '@/lib/data'

type CatalogSearchParams = Promise<{ category?: string }>

export default function CatalogPage({
  searchParams,
}: {
  searchParams: CatalogSearchParams
}) {
  return (
    <main>
      <h1>Catalog</h1>
      <Suspense fallback={<p>Loading category...</p>}>
        <CategoryResults searchParams={searchParams} />
      </Suspense>
    </main>
  )
}

import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'Product catalog',
  description: 'Browse products by category',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}

import Link from 'next/link'

const categories = [
  { slug: 'featured', label: 'Featured products' },
  { slug: 'sale', label: 'Products on sale' },
]

export default function Home() {
  return (
    <main>
      <h1>Shop by category</h1>
      <ul>
        {categories.map((category) => (
          <li key={category.slug}>
            <Link href={`/catalog?category=${category.slug}`}>
              {category.label}
            </Link>
          </li>
        ))}
      </ul>

import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig

const productsByCategory: Record<string, string[]> = {
  featured: ['Desk Lamp', 'Wool Blanket'],
  sale: ['Canvas Tote', 'Travel Mug'],
}

export async function getProducts(category: string) {
  await new Promise((resolve) => setTimeout(resolve, 800))
  return productsByCategory[category] ?? []
}

